const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.seller_id)) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_SELLER_ID_FORMAT', message: 'seller_id must be a valid UUID.' } }];
}
if (!body.product_type || !body.marketplace_id) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'product_type and marketplace_id are both required.'
  }}];
}

return [{ json: {
  decision: 'VALID',
  seller_id: body.seller_id,
  product_type: body.product_type,
  marketplace_id: body.marketplace_id
}}];

const upstream = $input.first().json;
const req = $('Validate Input').first().json;

const valid = Array.isArray(upstream.valid_themes) ? upstream.valid_themes : null;

if (!valid) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'UPSTREAM_NO_THEME_DATA',
    product_type: req.product_type,
    marketplace_id: req.marketplace_id,
    message: 'wf15 returned no valid_themes. Confirm the product type is a real Amazon product type for this marketplace, and that wf15 is Active.',
    upstream_raw: upstream
  }}];
}

const deprecated = Array.isArray(upstream.deprecated_themes) ? upstream.deprecated_themes : [];
const deprecatedSet = new Set(deprecated);

// wf15's per-theme resolved attribute name(s) (its KNOWN_VERIFIED_ATTRIBUTES
// override plus schema-parse result), keyed by theme string - e.g.
// theme_attribute_map['SIZE/COLOR'] = ['size_name', 'color']. This was
// never actually read here despite this node's own job being to pass it
// through as real_attributes on each theme option: theme-selection.jsx
// has been reading selectedPicked.real_attributes since it shipped, but
// it was always undefined coming from this workflow, so new-parent mode -
// which has no other source for a real attribute name; see that file's
// own useParentReal/useSchemaReal comment - has been falling straight
// through to the hardcoded THEME_ATTRIBUTE_MAP guess this whole time,
// bypassing the §6 fix entirely for the one mode that most needed it.
// Confirmed by reading both sides directly, not assumed.
const themeAttributeMap = upstream.theme_attribute_map || {};

// Core Day 17 rule: only offer themes Amazon is NOT retiring.
// Real-data example (SHIRT): COLOR/SIZE is deprecated, SIZE/COLOR is not.
const usable = valid.filter(function(t) { return !deprecatedSet.has(t); });

// Slash segments ARE the dimensions: 'SIZE/COLOR' = 2-dimension theme.
const parsed = usable.map(function(t) {
  return { theme: t, dimensions: t.split('/'), real_attributes: themeAttributeMap[t] || null };
});

const singleDimension = parsed.filter(function(p) { return p.dimensions.length === 1; });
const twoDimension = parsed.filter(function(p) { return p.dimensions.length === 2; });

// V1 supports 1 or 2 dimensions (GUI spec). 3+ segment themes are excluded
// from the picker lists but returned openly below - never silently hidden.
const excludedOverTwo = parsed
  .filter(function(p) { return p.dimensions.length > 2; })
  .map(function(p) { return p.theme; });

return [{ json: {
  decision: 'OPTIONS_READY',
  product_type: req.product_type,
  marketplace_id: req.marketplace_id,
  counts: {
    valid_total: valid.length,
    deprecated_total: deprecated.length,
    usable_total: usable.length,
    single_dimension: singleDimension.length,
    two_dimension: twoDimension.length,
    excluded_over_two_dimensions: excludedOverTwo.length
  },
  single_dimension_themes: singleDimension,
  two_dimension_themes: twoDimension,
  excluded_over_two_dimensions: excludedOverTwo,
  product_type_version: upstream.product_type_version || null,
  fetched_at: upstream.fetched_at || null,
  // For the structured-attribute design - a flat map, same shape wf15
  // itself uses, not duplicated per-theme. Multiple themes can share the
  // same candidate attribute (e.g. a plain "color" candidate could
  // appear both standalone and inside a matrix theme); one shared map
  // keyed by attribute name is what stays consistent if either theme's
  // candidate list changes, rather than two copies that could drift.
  // theme-selection.jsx looks this up by whichever candidate name it's
  // actually resolving, not by theme.
  attribute_schemas: upstream.attribute_schemas || {}
}}];
